"""Holding a slot for a TTL, then confirming it."""

from __future__ import annotations


class SlotTaken(Exception):
    """Raised when a slot is already held or booked."""


class HoldExpired(Exception):
    """Raised when a confirm arrives after the hold's deadline."""


class Reservations:
    """Reserve a slot for ``ttl`` seconds, then confirm or lose it.

    A hold is recorded with the time it was taken. It is live while
    ``now <= reserved_at + ttl`` (the deadline is inclusive); after that
    it expires and the slot becomes free again. A confirmed booking is
    permanent.
    """

    def __init__(self, ttl: float) -> None:
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self.ttl = ttl
        self._holds: dict[str, float] = {}      # slot -> reserved_at
        self._confirmed: set[str] = set()

    def _is_live(self, slot: str, now: float) -> bool:
        """Is there a live (unexpired) hold on ``slot`` at ``now``?"""
        reserved_at = self._holds.get(slot)
        if reserved_at is None:
            return False
        return now <= reserved_at + self.ttl

    def reserve(self, slot: str, now: float) -> float:
        """Hold ``slot`` at ``now``; return the expiry time."""
        if slot in self._confirmed:
            raise SlotTaken(slot)
        if self._is_live(slot, now):
            raise SlotTaken(slot)
        self._holds[slot] = now
        return now + self.ttl

    def confirm(self, slot: str, now: float) -> None:
        """Finalize a held slot. Raises HoldExpired after the deadline."""
        if slot in self._confirmed:
            return
        if not self._is_live(slot, now):
            raise HoldExpired(f"{slot}: no live hold")
        del self._holds[slot]
        self._confirmed.add(slot)

    def is_free(self, slot: str, now: float) -> bool:
        """Is ``slot`` available to reserve at ``now``?"""
        return slot not in self._confirmed and not self._is_live(slot, now)

"""Applying sequenced account-update messages exactly once."""

from __future__ import annotations


class Consumer:
    """Apply (account, seq, delta) messages to per-account balances.

    Each account carries a monotonically increasing sequence number. A message
    is applied only when its sequence is exactly the next one expected for that
    account. Redeliveries and stale (older) messages are dropped, and messages
    that arrive ahead of a gap are held until the gap is filled.
    """

    def __init__(self) -> None:
        self.balances: dict[str, int] = {}
        # Next sequence number expected per account; sequences start at 1.
        self._next_seq: dict[str, int] = {}
        # Held messages that arrived ahead of a gap: account -> {seq: delta}.
        self._pending: dict[str, dict[int, int]] = {}

    def apply(self, account: str, seq: int, delta: int) -> bool:
        """Apply ``delta`` to ``account``'s balance. Returns True if applied."""
        next_seq = self._next_seq.get(account, 1)

        # Stale redelivery or already-applied message: drop it.
        if seq < next_seq:
            return False

        # A gap: hold the message until the missing sequence arrives.
        if seq > next_seq:
            self._pending.setdefault(account, {})[seq] = delta
            return False

        # seq == next_seq: apply it and flush any held messages that now
        # become contiguous.
        self._apply(account, delta)
        next_seq += 1

        pending = self._pending.get(account)
        while pending is not None and next_seq in pending:
            self._apply(account, pending.pop(next_seq))
            next_seq += 1

        self._next_seq[account] = next_seq
        return True

    def _apply(self, account: str, delta: int) -> None:
        self.balances[account] = self.balances.get(account, 0) + delta

    def balance(self, account: str) -> int:
        return self.balances.get(account, 0)

"""A cache bounded by time-to-live and by least-recently-used capacity."""

from __future__ import annotations


class LruTtlCache:
    """Hold at most ``cap`` entries, each living at most ``ttl`` seconds.

    An entry expires ``ttl`` seconds after it was last set.  A ``get`` that
    finds a live entry refreshes its recency; a ``get`` that finds an expired
    entry drops it and returns ``None``.  When the cache is full, expired
    entries are discarded first, and any remaining eviction removes the live
    entry whose last use is oldest.
    """

    def __init__(self, cap: int, ttl: float) -> None:
        if cap < 1:
            raise ValueError("cap must be at least 1")
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self.cap = cap
        self.ttl = ttl
        # key -> [value, expires_at, last_used]
        self._store: dict[str, list] = {}

    def _expired(self, key: str, now: float) -> bool:
        return now >= self._store[key][1]

    def _drop_expired(self, now: float) -> None:
        for key in [k for k in self._store if self._expired(k, now)]:
            del self._store[key]

    def get(self, key: str, now: float) -> object | None:
        """Return the value for ``key``, or None if absent or expired."""
        entry = self._store.get(key)
        if entry is None:
            return None
        if now >= entry[1]:
            del self._store[key]
            return None
        entry[2] = now  # refresh recency
        return entry[0]

    def set(self, key: str, value: object, now: float) -> None:
        """Store ``value`` under ``key`` set at ``now``."""
        self._drop_expired(now)
        if key in self._store:
            self._store[key] = [value, now + self.ttl, now]
            return
        if len(self._store) >= self.cap:
            lru = min(self._store, key=lambda k: self._store[k][2])
            del self._store[lru]
        self._store[key] = [value, now + self.ttl, now]

    def __len__(self) -> int:
        return len(self._store)

"""A per-key call cap over a sliding time window."""

from __future__ import annotations


class RateLimitExceeded(Exception):
    """Raised when a key has spent its allowance in the current window."""


class RateLimiter:
    """Cap each key at ``limit`` calls per sliding ``window_s`` seconds.

    The window slides with the caller's own history: a call is allowed when
    fewer than ``limit`` calls by the same key landed in ``[now - window_s,
    now)`` (left-open) and denied otherwise.
    """

    def __init__(self, limit: int, window_s: float) -> None:
        if limit < 1:
            raise ValueError("limit must be at least 1")
        if window_s <= 0:
            raise ValueError("window_s must be positive")
        self.limit = limit
        self.window_s = window_s
        self._calls: dict[str, list[float]] = {}  # key -> ascending timestamps

    def _sweep(self, now: float) -> None:
        """Drop calls that fell out of the window for every key."""
        cutoff = now - self.window_s
        for key in list(self._calls):
            stamps = self._calls[key]
            # Keep only calls strictly inside (now - window_s, now].
            keep = [t for t in stamps if t > cutoff]
            if keep:
                self._calls[key] = keep
            else:
                del self._calls[key]

    def check(self, key: str, now: float) -> bool:
        """Would a call by ``key`` at ``now`` be allowed? Does not spend."""
        self._sweep(now)
        return len(self._calls.get(key, ())) < self.limit

    def call(self, key: str, now: float) -> float:
        """Record a call by ``key`` at ``now``; return the retry-after in seconds.

        Raises ``RateLimitExceeded`` when the sliding window is already full.
        """
        self._sweep(now)
        stamps = self._calls.get(key)
        if stamps is None:
            stamps = []
            self._calls[key] = stamps
        if len(stamps) >= self.limit:
            retry = stamps[0] + self.window_s - now
            raise RateLimitExceeded(f"{key}: retry in {retry:.3f}s")
        stamps.append(now)
        return 0.0

    def active_keys(self) -> int:
        """How many keys currently have a call inside the window."""
        return len(self._calls)

"""Holding a slot for a TTL, then confirming it."""

from __future__ import annotations


class SlotTaken(Exception):
    """Raised when a slot is already held or booked."""


class HoldExpired(Exception):
    """Raised when a confirm arrives after the hold's deadline."""


class Reservations:
    """Reserve a slot for ``ttl`` seconds, then confirm or lose it.

    A hold is live up to and including ``reserved_at + ttl``. Once that
    instant has passed the hold is dead: it can no longer be confirmed and
    the slot is free to be reserved again. A confirmed booking is permanent.
    """

    def __init__(self, ttl: float) -> None:
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self.ttl = ttl
        self._holds: dict[str, float] = {}      # slot -> reserved_at
        self._confirmed: set[str] = set()

    def _hold_is_live(self, slot: str, now: float) -> bool:
        """Is ``slot``'s hold still live at ``now`` (deadline inclusive)?"""
        reserved_at = self._holds.get(slot)
        if reserved_at is None:
            return False
        return now <= reserved_at + self.ttl

    def reserve(self, slot: str, now: float) -> float:
        """Hold ``slot`` at ``now``; return the expiry time."""
        if slot in self._confirmed:
            raise SlotTaken(slot)
        if slot in self._holds:
            if self._hold_is_live(slot, now):
                raise SlotTaken(slot)
            # The previous hold has expired: reclaim the slot.
            del self._holds[slot]
        self._holds[slot] = now
        return now + self.ttl

    def confirm(self, slot: str, now: float) -> None:
        """Finalize a held slot. Raises HoldExpired after the deadline."""
        if slot in self._confirmed:
            return
        if not self._hold_is_live(slot, now):
            self._holds.pop(slot, None)
            raise HoldExpired(f"{slot}: no live hold")
        del self._holds[slot]
        self._confirmed.add(slot)

    def is_free(self, slot: str, now: float) -> bool:
        """Is ``slot`` available to reserve at ``now``?"""
        if slot in self._confirmed:
            return False
        return not self._hold_is_live(slot, now)

