class LruTtlCache:
    """Hold at most ``cap`` entries, each living at most ``ttl`` seconds.

    An entry expires ``ttl`` seconds after it was set (a re-set refreshes the
    expiry). Reads refresh an entry's recency, and when the cache is full the
    least-recently-used live entry is evicted. Expired entries never occupy
    capacity: a set drops them before evicting by recency.
    """

    def __init__(self, cap: int, ttl: float) -> None:
        if cap < 1:
            raise ValueError("cap must be at least 1")
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self.cap = cap
        self.ttl = ttl
        # key -> (value, set_at, last_used)
        self._store: dict[str, tuple[object, float, float]] = {}

    def _expired(self, entry: tuple[object, float, float], now: float) -> bool:
        return now - entry[1] >= self.ttl

    def get(self, key: str, now: float) -> object | None:
        """Return the value for ``key``, or None if absent or expired."""
        entry = self._store.get(key)
        if entry is None:
            return None
        if self._expired(entry, now):
            del self._store[key]
            return None
        value, set_at, _ = entry
        self._store[key] = (value, set_at, now)  # refresh recency
        return value

    def set(self, key: str, value: object, now: float) -> None:
        """Store ``value`` under ``key`` set at ``now``."""
        # Drop expired entries so they never occupy capacity.
        for k in [k for k, e in self._store.items() if self._expired(e, now)]:
            del self._store[k]

        if key not in self._store and len(self._store) >= self.cap:
            lru = min(self._store, key=lambda k: self._store[k][2])
            del self._store[lru]

        self._store[key] = (value, now, now)

    def __len__(self) -> int:
        return len(self._store)

