class Consumer:
    """Apply (account, seq, delta) messages to per-account balances.

    Each account carries a monotonically increasing sequence number starting
    at 1. A message is applied only when its sequence is exactly the next one
    expected for that account. Redeliveries of an already-applied sequence are
    dropped, and out-of-order messages that arrive ahead of a gap are held
    until the gap is filled, then flushed in order.
    """

    def __init__(self) -> None:
        self.balances: dict[str, int] = {}
        # Next sequence number expected to be applied, per account.
        self._next_seq: dict[str, int] = {}
        # Held messages keyed by account, mapping seq -> delta.
        self._held: dict[str, dict[int, int]] = {}

    def apply(self, account: str, seq: int, delta: int) -> bool:
        """Apply ``delta`` to ``account``'s balance. Returns True if applied."""
        expected = self._next_seq.get(account, 1)

        if seq < expected:
            # Stale redelivery: already applied (or superseded). Drop it.
            return False

        if seq > expected:
            # Gap: hold the message until the missing sequences arrive.
            self._held.setdefault(account, {})[seq] = delta
            return False

        # seq == expected: apply it, then flush any now-contiguous held
        # messages for this account.
        self._apply(account, delta)
        expected += 1

        held = self._held.get(account)
        if held:
            while expected in held:
                self._apply(account, held.pop(expected))
                expected += 1
            if not held:
                del self._held[account]

        self._next_seq[account] = expected
        return True

    def _apply(self, account: str, delta: int) -> None:
        self.balances[account] = self.balances.get(account, 0) + delta

    def balance(self, account: str) -> int:
        return self.balances.get(account, 0)

