    An entry expires ``ttl`` seconds after it was last set. A ``get`` refreshes
    the entry's recency, and when the cache is full the live entry whose last
    use is oldest is evicted. Expired entries never occupy capacity: a ``set``
    drops them before evicting by recency.
    """

    def __init__(self, cap: int, ttl: float) -> None:
        if cap < 1:
            raise ValueError("cap must be at least 1")
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self.cap = cap
        self.ttl = ttl
        # key -> (value, expires_at), ordered from least to most recently used.
        self._store: dict[str, tuple[object, float]] = {}

    def _is_expired(self, entry: tuple[object, float], now: float) -> bool:
        return now >= entry[1]

    def _purge_expired(self, now: float) -> None:
        expired = [k for k, e in self._store.items() if self._is_expired(e, now)]
        for key in expired:
            del self._store[key]

    def get(self, key: str, now: float) -> object | None:
        """Return the value for ``key``, or None if absent or expired."""
        entry = self._store.get(key)
        if entry is None:
            return None
        if self._is_expired(entry, now):
            del self._store[key]
            return None
        # Refresh recency by moving the key to the most-recent end.
        del self._store[key]
        self._store[key] = entry
        return entry[0]

    def set(self, key: str, value: object, now: float) -> None:
        """Store ``value`` under ``key`` set at ``now``."""
        self._purge_expired(now)
        if key in self._store:
            del self._store[key]
