        """Return the value for ``key``, or None if absent or expired."""
        entry = self._store.get(key)
        if entry is None:
            return None
        if self._is_expired(entry, now):
            del self._store[key]
            return None
        value, set_at, _ = entry
        self._store[key] = (value, set_at, now)
        return value

    def set(self, key: str, value: object, now: float) -> None:
        """Store ``value`` under ``key`` set at ``now``."""
        # An expired entry never occupies capacity: drop all expired entries.
        for k in list(self._store):
            if self._is_expired(self._store[k], now):
                del self._store[k]

        if key not in self._store and len(self._store) >= self.cap:
            lru = min(self._store, key=lambda k: self._store[k][2])
