        """Drop timestamps at or before ``now - window_s`` for ``key``."""
        history = self._history.get(key)
        if history is None:
            return deque()
        cutoff = now - self.window_s
        while history and history[0] <= cutoff:
            history.popleft()
        return history

    def _sweep(self, now: float) -> None:
        """Drop expired history for every key, removing keys gone quiet."""
        cutoff = now - self.window_s
        for key in list(self._history):
            history = self._history[key]
            while history and history[0] <= cutoff:
                history.popleft()
            if not history:
                del self._history[key]

    def check(self, key: str, now: float) -> bool:
        """Would a call by ``key`` at ``now`` be allowed? Does not spend."""
        history = self._prune(key, now)
        return len(history) < self.limit

