        """Apply ``delta`` to ``account``'s balance. Returns True if applied."""
        last = self._last_seq.get(account, 0)

        if seq <= last:
            # Duplicate or stale redelivery: no-op.
            return False

        if seq > last + 1:
            # Gap: hold the message until the missing ones arrive.
            self._held.setdefault(account, {})[seq] = delta
            return False

        # seq == last + 1: apply, then flush any now-contiguous held messages.
        applied = False
        self._apply(account, delta)
        last += 1
        held = self._held.get(account)
        while held and last + 1 in held:
            self._apply(account, held.pop(last + 1))
            last += 1
        self._last_seq[account] = last
        return True

    def _apply(self, account: str, delta: int) -> None:
        self.balances[account] = self.balances.get(account, 0) + delta

    def balance(self, account: str) -> int:
        return self.balances.get(account, 0)

