from collections import deque


class RateLimitExceeded(Exception):
    """Raised when a key has spent its allowance in the current window."""


class RateLimiter:
    """Cap each key at ``limit`` calls per sliding ``window_s`` seconds.

    The window follows each caller's own history: a call at ``now`` is allowed
    when fewer than ``limit`` calls by the same key landed in ``[now - W, now)``.
    The interval is left-open, so a call exactly ``W`` seconds after an earlier
    one does not count that earlier call.
    """

    def __init__(self, limit: int, window_s: float) -> None:
        if limit < 1:
            raise ValueError("limit must be at least 1")
        if window_s <= 0:
            raise ValueError("window_s must be positive")
        self.limit = limit
        self.window_s = window_s
        self._calls: dict[str, deque[float]] = {}

    def _sweep(self, now: float) -> None:
        """Drop calls outside ``[now - W, now)`` for every key.

        Keys left with no calls in the window are forgotten, so memory does
        not grow with keys that have gone quiet.
        """
        cutoff = now - self.window_s
        for key in list(self._calls):
            calls = self._calls[key]
            while calls and calls[0] <= cutoff:
                calls.popleft()
            if not calls:
                del self._calls[key]

    def _prune(self, key: str, now: float) -> deque[float]:
        cutoff = now - self.window_s
        calls = self._calls.get(key)
        if calls is None:
            calls = deque()
            self._calls[key] = calls
        else:
            while calls and calls[0] <= cutoff:
                calls.popleft()
        return calls

    def check(self, key: str, now: float) -> bool:
        """Would a call by ``key`` at ``now`` be allowed? Does not spend."""
        self._sweep(now)
        calls = self._calls.get(key)
        if calls is None:
            return True
        return len(calls) < self.limit

    def call(self, key: str, now: float) -> float:
        """Record a call by ``key`` at ``now``; return the retry-after in seconds.

        Raises ``RateLimitExceeded`` when ``limit`` calls already landed in the
        last ``window_s`` seconds.
        """
        self._sweep(now)
        calls = self._prune(key, now)
        if len(calls) >= self.limit:
            retry = calls[0] + self.window_s - now
            raise RateLimitExceeded(f"{key}: retry in {retry:.3f}s")
        calls.append(now)
        return 0.0

    def active_keys(self) -> int:
        """How many keys currently have at least one call in the window."""
        return len(self._calls)

