        if cap < 1:
            raise ValueError("cap must be at least 1")
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self.cap = cap
        self.ttl = ttl
        # key -> (value, set_at); dict order is least- to most-recently used.
        self._store: dict[str, tuple[object, float]] = {}

    def _expired(self, set_at: float, now: float) -> bool:
        return now - set_at >= self.ttl

    def get(self, key: str, now: float) -> object | None:
        """Return the value for ``key``, or None if absent or expired."""
        entry = self._store.get(key)
        if entry is None:
            return None
        value, set_at = entry
        if self._expired(set_at, now):
            del self._store[key]
            return None
        # Refresh recency: move to the most-recently-used end.
        del self._store[key]
        self._store[key] = (value, set_at)
        return value

    def set(self, key: str, value: object, now: float) -> None:
        """Store ``value`` under ``key`` set at ``now``."""
        # An expired entry never occupies capacity: drop all expired entries.
        for k in [k for k, (_, set_at) in self._store.items() if self._expired(set_at, now)]:
            del self._store[k]
        if key in self._store:
            del self._store[key]
        elif len(self._store) >= self.cap:
            lru = next(iter(self._store))  # least-recently-used
            del self._store[lru]
        self._store[key] = (value, now)

    def __len__(self) -> int:
        return len(self._store)

